// Cruza cada cliente recebido no Webhook com as opções de investimento
// do perfil correspondente (lidas do docs/data.csv via HTTP Request + Extract From File).

const clientes = $('Webhook Clientes').first().json.body.clientes;
const opcoes = $input.first().json.opcoes;

const contextoPerfil = {
  Conservador: 'prioriza segurança e liquidez, aceita pouca oscilação no patrimônio',
  Moderado: 'busca equilíbrio entre segurança e rentabilidade, tolera alguma oscilação',
  Arrojado: 'busca maior rentabilidade no longo prazo e aceita mais oscilação e risco'
};

return clientes.map((cliente) => {
  const opcoesPerfil = opcoes.filter((o) => o.perfil === cliente.perfil);

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      perfil: cliente.perfil,
      contexto_perfil: contextoPerfil[cliente.perfil] || '',
      opcoes: opcoesPerfil
    }
  };
});

