// Formata a saida final: dados do cliente + mensagem gerada pelo Agente de IA.
// O Agente de IA (LangChain) substitui o json do item pela sua propria saida,
// entao buscamos nome/email/perfil de volta no node "Montar Recomendacoes",
// casando pelo indice (a ordem dos itens e preservada pelo Agente).
// Processa todos os itens de uma vez (evita corrida com o node de Aggregate
// quando o Webhook responde no modo "When Last Node Finishes").
const originais = $('Montar Recomendações').all();
return $input.all().map((entry, index) => {
  const original = originais[index] ? originais[index].json : {};
  const item = entry.json;
  return {
    json: {
      nome: original.nome,
      email: original.email,
      perfil: original.perfil,
      mensagem: item.output || item.text
    }
  };
});
